import {
  useCallback,
  useLayoutEffect,
  useRef,
  type ComponentProps,
  type CSSProperties,
  type ReactNode,
} from 'react'
import { Field } from '@base-ui/react/field'
import { cn } from '@/lib/utils'
import {
  assignRef,
  InputField,
  boxClass,
  focusControl,
  inputStyles,
  type InputSize,
  type ValidationState,
} from './InputField'
import styles from './Textarea.module.css'

export interface TextareaProps extends Omit<ComponentProps<'textarea'>, 'size'> {
  label?: ReactNode
  helperText?: ReactNode
  validationState?: ValidationState
  size?: InputSize
  isFullWidth?: boolean
  /** Which way the user can drag to resize. Ignored with `hasAutoSize`. */
  resize?: 'none' | 'both' | 'vertical' | 'horizontal'
  /** Grow and shrink with the content, between `minRows` and `maxRows`. */
  hasAutoSize?: boolean
  /** The starting height, in lines. */
  minRows?: number
  /** The most it grows to before scrolling, in lines. */
  maxRows?: number
}

export function Textarea({
  label,
  helperText,
  validationState,
  size = 'md',
  isFullWidth,
  resize = 'vertical',
  hasAutoSize = false,
  minRows = 3,
  maxRows,
  required,
  disabled,
  name,
  className,
  onInput,
  ref,
  style,
  ...props
}: TextareaProps) {
  const inner = useRef<HTMLTextAreaElement | null>(null)
  const fit = useCallback(() => {
    const el = inner.current
    if (!el || !hasAutoSize) return
    // Collapse first so a shrinking value can shrink the box; max-block-size
    // (from maxRows) caps the result and the rest scrolls.
    el.style.blockSize = 'auto'
    el.style.blockSize = `${el.scrollHeight}px`
  }, [hasAutoSize])
  // Controlled values change without an input event; fit to those too.
  useLayoutEffect(fit, [fit, props.value])

  return (
    <InputField
      label={label}
      helperText={helperText}
      validationState={validationState}
      required={required}
      disabled={disabled}
      name={name}
      isFullWidth={isFullWidth}
      className={className}
    >
      <span className={cn(boxClass(size), styles.multiline, styles[`pad-${size}`])} onMouseDown={focusControl}>
        <Field.Control
          render={
            <textarea
              rows={minRows}
              ref={(node) => {
                inner.current = node
                assignRef(ref, node)
              }}
            />
          }
          {...(props as ComponentProps<typeof Field.Control>)}
          required={required}
          onInput={(event) => {
            fit()
            onInput?.(event as unknown as Parameters<NonNullable<TextareaProps["onInput"]>>[0])
          }}
          className={cn(inputStyles.control, styles.textarea)}
          style={
            {
              ...style,
              resize: hasAutoSize ? 'none' : resize,
              ...(maxRows && { maxBlockSize: `calc(${maxRows} * 1lh + 2 * var(--pad-block))` }),
            } as CSSProperties
          }
        />
      </span>
    </InputField>
  )
}

/* A textarea's box grows with it, so it takes vertical padding instead of a
   fixed height: 6px at sm, 8px at md, which puts the first line where a
   single-line field of the same size puts its text. The padding sits on the
   <textarea>, not the box, so the browser's resize handle lands in the
   field's corner. Doubled classes outrank the shared size classes,
   whichever stylesheet loads first. */
.multiline.multiline {
  align-items: stretch;
  min-block-size: 0;
  padding: 0;
}
.pad-sm {
  --pad-block: var(--space-1-5);
  --pad-inline: var(--space-2);
}
.pad-md {
  --pad-block: var(--space-2);
  --pad-inline: var(--space-2-5);
}

.textarea.textarea {
  display: block;
  box-sizing: border-box;
  inline-size: 100%;
  padding: var(--pad-block) var(--pad-inline);
  overflow-y: auto;
}
